// Family-room ReSpeaker wedge alert.
//
// The satellite fails SILENTLY when the mic array wedges: the service stays
// active, /health returns {"ok": true}, nothing is logged. It has been found
// twice only because someone stood in the family room talking to a dead mic.
// pw-poller-pi's mic_health.sh publishes this topic (RETAINED) every 10 min.

const p = msg.payload || {};
const cur = p.ok === true;
const reason = p.reason || 'unknown';
const prev = context.get('last');
context.set('last', cur);

node.status({fill: cur ? 'green' : 'red', shape: 'dot',
             text: (cur ? 'ok' : 'WEDGED') + ' — ' + reason});

// The topic is retained, so a deploy or Node-RED restart replays the current
// state immediately. Staying quiet on a healthy replay stops every deploy
// firing a bogus "recovered". But if it replays as BROKEN, say so — a missed
// alert is the exact failure this flow exists to prevent.
if (prev === undefined) {
    if (cur) { return null; }
    msg.title = 'Family room mic is dead (still)';
    msg.payload = 'ReSpeaker wedged (' + reason + '). Voice satellite is deaf. '
                + 'Unplug and replug its USB — no software reset clears this.';
    msg.priority = 1;
    msg.device = global.get('BradPhoneNM');
    return msg;
}

if (prev === cur) { return null; }   // transition-only

msg.device = global.get('BradPhoneNM');
if (cur) {
    msg.title = 'Family room mic recovered';
    msg.payload = 'The ReSpeaker is streaming again.';
    msg.priority = 0;
} else {
    msg.title = 'Family room mic is dead';
    msg.payload = 'ReSpeaker wedged (' + reason + '). Voice satellite is deaf. '
                + 'Unplug and replug its USB — no software reset clears this.';
    msg.priority = 1;
}
return msg;
